&lt;h3 id=&#34;Design-Patterns&#34;&gt;&lt;a href=&#34;#Design-Patterns&#34; class=&#34;headerlink&#34; title=&#34;Design Patterns&#34;&gt;&lt;/a&gt;Design Patterns&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Pattern&lt;/th&gt;
&lt;th&gt;Usage&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Builder&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Logger, Router, QuerySet&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Trait abstraction&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Cache, KvStore, SearchEngine, GraphDB, TimeSeriesDB&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Derive macros&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;#[derive(Model)]&lt;/code&gt;, &lt;code&gt;#[derive(Config)]&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Feature gates&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Driver implementations compiled on demand (redis, memcached, elasticsearch, etc.)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Filter chain&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Request filter chain, modeled on Beego Filter&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
