&lt;h3 id=&#34;License&#34;&gt;&lt;a href=&#34;#License&#34; class=&#34;headerlink&#34; title=&#34;License&#34;&gt;&lt;/a&gt;License&lt;/h3&gt;&lt;p&gt;Apache-2.0&lt;/p&gt;

 &lt;!-- Copyright (c) 2026 erik &lt;erik@erik.xyz&gt; — https://erik.xyz --&gt;
&lt;h1 id=&#34;Beerust&#34;&gt;&lt;a href=&#34;#Beerust&#34; class=&#34;headerlink&#34; title=&#34;Beerust&#34;&gt;&lt;/a&gt;Beerust&lt;/h1&gt;&lt;p&gt;&lt;a href=&#34;https://github.com/erikwang2013/bee-rust/blob/main/README.en.md&#34;&gt;English&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;Beerust是一个 Rust 语言的生产级 Web 框架，设计哲学源自 Go 的 Beego框架，用 Rust 惯用的 trait、macro、类型系统重新表达。&lt;/p&gt;
&lt;h2 id=&#34;设计目标&#34;&gt;&lt;a href=&#34;#设计目标&#34; class=&#34;headerlink&#34; title=&#34;设计目标&#34;&gt;&lt;/a&gt;设计目标&lt;/h2&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;目标&lt;/th&gt;
&lt;th&gt;指标&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;开发体验&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;从 &lt;code&gt;Beerust new&lt;/code&gt; 到首请求 &amp;lt; 30 秒&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;性能&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;控制器层开销 &amp;lt; 5%（对比裸 axum），P99 路由延迟 &amp;lt; 100µs&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;编译速度&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;元 crate 全量编译 &amp;lt; 60s（release），增量编译 &amp;lt; 5s&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;二进制体积&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;最小应用（仅 router）&amp;lt; 5MB（strip + LTO）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;安全性&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;0 unsafe 业务代码；所有 FFI 封装在独立 &lt;code&gt;*-sys&lt;/code&gt; crate&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;兼容性&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Rust 1.80+ MSRV，跟踪 stable&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;span id=&#34;more&#34;&gt;&lt;/span&gt;
&lt;h2 id=&#34;设计原则&#34;&gt;&lt;a href=&#34;#设计原则&#34; class=&#34;headerlink&#34; title=&#34;设计原则&#34;&gt;&lt;/a&gt;设计原则&lt;/h2&gt;&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;Beego 哲学，Rust 表达&lt;/strong&gt; — MVC、命名空间、过滤器链，用 trait + macro 实现&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;渐进增强&lt;/strong&gt; — 最小核心只依赖 axum + tokio，其他全部 feature gate&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;显式优于隐式&lt;/strong&gt; — 路由注册、模型映射、中间件顺序全部代码显式声明&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;零成本抽象&lt;/strong&gt; — trait 静态分发，macro 编译期展开，不引入虚函数开销&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;存储引擎独立性&lt;/strong&gt; — 每个引擎 trait 可单独替换实现，不影响上层业务&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;观测性内置&lt;/strong&gt; — tracing + metrics 埋点全框架覆盖，结构化日志默认开启&lt;/li&gt;
&lt;/ol&gt;
&lt;h2 id=&#34;架构设计&#34;&gt;&lt;a href=&#34;#架构设计&#34; class=&#34;headerlink&#34; title=&#34;架构设计&#34;&gt;&lt;/a&gt;架构设计&lt;/h2&gt;&lt;h3 id=&#34;Crate-拓扑&#34;&gt;&lt;a href=&#34;#Crate-拓扑&#34; class=&#34;headerlink&#34; title=&#34;Crate 拓扑&#34;&gt;&lt;/a&gt;Crate 拓扑&lt;/h3&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;bee_rust/           # 元 crate，re-export + feature flags&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_router/         # 路由 + 控制器 + Context + 过滤器链&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_orm/            # ORM — Model trait + QuerySet + Migration + 关系映射&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_kv/             # KV/Cache 统一抽象 — Redis + Memcached&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_search/         # 搜索/分析引擎 — Elasticsearch + OpenSearch + ClickHouse&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_graph/          # 图数据库 — Neo4j + NebulaGraph + ArangoDB&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_tsdb/           # 时序数据库 — InfluxDB + Apache IoTDB + QuestDB&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_config/         # 配置管理 — INI/YAML/ENV + 热更新&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_cache/          # 缓存抽象 — Memory/Redis/Memcache&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_session/        # Session — Memory/Redis/Cookie/Database 后端&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_logs/           # 日志 — 多级日志 + tracing 集成&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_template/       # 模板渲染 — 基于 tera&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_cli/            # CLI — 脚手架/代码生成/热重载/迁移&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;架构图&#34;&gt;&lt;a href=&#34;#架构图&#34; class=&#34;headerlink&#34; title=&#34;架构图&#34;&gt;&lt;/a&gt;架构图&lt;/h3&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;27&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;28&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;29&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;30&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;31&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;32&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;33&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;34&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;35&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;                        ┌───────────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                        │  bee_rust  (meta)      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                        │  re-export + features  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                        └───────────┬───────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                                    │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            ┌───────────────────────┼───────────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            │                       │                       │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;   ┌────────▼────────┐    ┌────────▼────────┐    ┌────────▼────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;   │    Web Layer     │    │   Data Layer    │    │   Tool Layer    │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;   └────────┬────────┘    └────────┬────────┘    └────────┬────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            │                       │                       │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌───────────┼───────────┐  ┌───────┼───────┐  ┌───────────┼───────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│ bee_router            │  │ bee_orm        │  │ bee_cli               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  - route register     │  │  - Model/Query  │  │  - scaffolding        │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  - controller trait   │  │  - Migration   │  │  - hot reload          │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  - filter chain       │  │  - Connection   │  │  - code generation    │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  - param extract      │  │                 │  │                       │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├────────────────────────┤  ├────────────────┤  ├───────────────────────┤&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│ bee_template           │  │ bee_config     │  │ bee_logs              │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  - template render     │  │  - INI/YAML/ENV│  │  - multi-level log    │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  - HTML/JSON           │  │  - hot reload   │  │  - tracing integrate  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├────────────────────────┤  ├────────────────┤  └───────────────────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│ bee_session            │  │ bee_cache      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  - session management  │  │  - cache trait  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  - multi-backend       │  │  - Mem/Redis    │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└────────────────────────┘  └────────────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌─────────────────────────────────────────────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│                   Storage Engine Layer                   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├──────────────────┬──────────────────────────────────────┤&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│ bee_kv           │  Redis + Memcached                   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│ bee_search       │  Elasticsearch + OpenSearch + ClickHouse │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│ bee_graph        │  Neo4j + NebulaGraph + ArangoDB      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│ bee_tsdb         │  InfluxDB + Apache IoTDB + QuestDB   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└──────────────────┴──────────────────────────────────────┘&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;Crate-依赖关系&#34;&gt;&lt;a href=&#34;#Crate-依赖关系&#34; class=&#34;headerlink&#34; title=&#34;Crate 依赖关系&#34;&gt;&lt;/a&gt;Crate 依赖关系&lt;/h3&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;bee_config (无依赖)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_logs   (无依赖)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_cache  → bee_config&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_kv     → bee_config&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_session → bee_cache, bee_config&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_template (无依赖)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_orm    → bee_config, bee_cache&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_search → bee_config&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_graph  → bee_config&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_tsdb   → bee_config&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_router → bee_session, bee_template, bee_config, bee_logs&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_cli    → bee_router, bee_orm&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bee_rust   → 全部上述 crate (re-export)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
