&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;RDBMS&lt;/td&gt;
&lt;td&gt;SQLite&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ecat-data-sqlx&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;a href=&#34;https://crates.io/crates/sqlx&#34;&gt;sqlx&lt;/a&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;RDBMS&lt;/td&gt;
&lt;td&gt;PostgreSQL&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ecat-data-sqlx&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;a href=&#34;https://crates.io/crates/sqlx&#34;&gt;sqlx&lt;/a&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;RDBMS&lt;/td&gt;
&lt;td&gt;MySQL&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ecat-data-sqlx&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;a href=&#34;https://crates.io/crates/sqlx&#34;&gt;sqlx&lt;/a&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;RDBMS&lt;/td&gt;
&lt;td&gt;TiDB&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ecat-data-sqlx&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;a href=&#34;https://crates.io/crates/sqlx&#34;&gt;sqlx&lt;/a&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;缓存&lt;/td&gt;
&lt;td&gt;Redis&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ecat-data-redis&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;a href=&#34;https://crates.io/crates/redis&#34;&gt;redis-rs&lt;/a&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
