&lt;td&gt;&lt;a href=&#34;https://crates.io/crates/opensearch&#34;&gt;opensearch&lt;/a&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;搜索&lt;/td&gt;
&lt;td&gt;Elasticsearch&lt;/td&gt;
